"""fx3rt: runtime support for Python code generated by fx3c.

It covers the fx3 rules that Python doesn't give for free: 64-bit integer
overflow errors, `/` vs `~/`, none-safe helpers, value semantics for
collections, panics, and fx3-style printing (true / false / none).
"""

from __future__ import annotations

import functools
import math
import sys
from typing import NoReturn

MISSING = object()


# ---------------------------------------------------------------------------
# Errors and panics (Syntax/errors.fx3)
# ---------------------------------------------------------------------------

class Error(Exception):
    """Base of every fx3 failure (@fails)."""

    def __init__(self, message: str = "", **fields):
        super().__init__(message)
        self.message = message
        for k, v in fields.items():
            setattr(self, k, v)

    def __str__(self) -> str:
        return f"{type(self).__name__}: {self.message}" if self.message else type(self).__name__


class ValueError(Error): pass          # noqa: E701,A001
class ParseError(ValueError): pass     # noqa: E701
class IOError(Error): pass             # noqa: E701,A001
class FileNotFound(IOError): pass      # noqa: E701
class PermissionDenied(IOError): pass  # noqa: E701
class NetworkError(Error): pass        # noqa: E701
class TimeoutError(NetworkError): pass     # noqa: E701,A001
class ConnectionError(NetworkError): pass  # noqa: E701,A001
class FormatError(Error): pass         # noqa: E701
class DbError(Error): pass             # noqa: E701
class AiError(Error): pass             # noqa: E701


class Panic(Exception):
    """A bug: stops the program. Never caught by `catch`."""


def panic(message: str = "panic") -> NoReturn:
    raise Panic(message)


def ensure(cond: bool, message: str = "ensure failed") -> None:
    if not cond:
        raise Panic(message)


def exit(code: int = 0) -> NoReturn:  # noqa: A001
    raise SystemExit(code)


# ---------------------------------------------------------------------------
# Integers (Syntax/operators.fx3 sections 1-2)
# ---------------------------------------------------------------------------

_RANGES = {
    "i8": (-2**7, 2**7 - 1), "i16": (-2**15, 2**15 - 1), "i32": (-2**31, 2**31 - 1),
    "int": (-2**63, 2**63 - 1), "i128": (-2**127, 2**127 - 1),
    "u8": (0, 2**8 - 1), "u16": (0, 2**16 - 1), "u32": (0, 2**32 - 1),
    "u64": (0, 2**64 - 1), "u128": (0, 2**128 - 1),
}
_I64_MIN, _I64_MAX = _RANGES["int"]


def i64(x: int) -> int:
    if _I64_MIN <= x <= _I64_MAX:
        return x
    raise Panic(f"integer overflow: {x} doesn't fit in int (64-bit)")


def fit(x: int, kind: str) -> int:
    lo, hi = _RANGES[kind]
    if lo <= x <= hi:
        return x
    raise Panic(f"integer overflow: {x} doesn't fit in {kind} ({lo} to {hi})")


def div(a, b) -> float:
    """`/`: always a float. x / 0.0 gives inf / nan (IEEE 754); int / int 0 is an error."""
    if b == 0:
        if isinstance(a, int) and isinstance(b, int):
            raise Panic("division by zero")
        if a == 0 or a != a:
            return math.nan
        return math.copysign(math.inf, a) * math.copysign(1.0, b)
    return a / b


def floordiv(a, b):
    """`~/`: floor division."""
    if b == 0:
        if isinstance(a, int) and isinstance(b, int):
            raise Panic("division by zero")
        return math.nan if a == 0 else math.copysign(math.inf, a)
    return a // b


def mod(a, b):
    if b == 0:
        if isinstance(a, int) and isinstance(b, int):
            raise Panic("division by zero (in %)")
        return math.nan
    return a % b


def cast(x, kind: str):
    """`x as T`: checked."""
    if kind in _RANGES:
        if isinstance(x, float):
            if x != x or x in (math.inf, -math.inf):
                raise Panic(f"can't convert {show(x)} to {kind}")
            x = int(x)               # toward zero
        elif isinstance(x, str):     # char -> int
            x = ord(x)
        return fit(x, kind)
    if kind in ("float", "f32"):
        return float(x)
    if kind == "char":
        return chr(x)
    return x


def try_cast(x, kind: str):
    """`x as? T`: none if it doesn't fit."""
    try:
        return cast(x, kind)
    except Panic:
        return None


def wrap(x, kind: str):
    """`x as! T`: wraps around (two's complement)."""
    if kind in _RANGES:
        if isinstance(x, float):
            x = int(x)
        lo, hi = _RANGES[kind]
        span = hi - lo + 1
        return (x - lo) % span + lo
    return cast(x, kind)


def in_range(x, lo, hi, name: str):
    if lo <= x <= hi:
        return x
    raise Panic(f"{name} = {show(x)} is outside @range({show(lo)}, {show(hi)})")


def round(x, digits: int | None = None):  # noqa: A001
    """Half away from zero (round(2.5) == 3), not Python's banker's rounding."""
    if digits is None:
        return int(math.floor(abs(x) + 0.5)) * (1 if x >= 0 else -1)
    f = 10 ** digits
    return math.floor(abs(x) * f + 0.5) / f * (1 if x >= 0 else -1)


def floor(x) -> int:
    return math.floor(x)


def ceil(x) -> int:
    return math.ceil(x)


def irange(start: int, end: int, step: int = 1) -> range:
    """An inclusive range a..=b with any step."""
    if step == 0:
        raise Panic("a range step can't be 0")
    return range(start, end + (1 if step > 0 else -1), step)


# ---------------------------------------------------------------------------
# Text (Syntax/strings.fx3)
# ---------------------------------------------------------------------------

def show(x) -> str:
    """How fx3 prints a value."""
    if x is None:
        return "none"
    if x is True:
        return "true"
    if x is False:
        return "false"
    if isinstance(x, str):
        return x
    if isinstance(x, float):
        if x != x:
            return "nan"
        if x in (math.inf, -math.inf):
            return "inf" if x > 0 else "-inf"
        return repr(x)
    if isinstance(x, (list, tuple, set, dict)):
        return _show_nested(x)
    return str(x)


def _show_nested(x) -> str:
    if isinstance(x, str):
        return '"' + x.replace('"', '\\"') + '"'
    if isinstance(x, list):
        return "[" + ", ".join(_show_nested(v) for v in x) + "]"
    if isinstance(x, tuple):
        return "(" + ", ".join(_show_nested(v) for v in x) + ("," if len(x) == 1 else "") + ")"
    if isinstance(x, set):
        try:
            items = sorted(x)
        except TypeError:
            items = list(x)
        return "{" + ", ".join(_show_nested(v) for v in items) + "}"
    if isinstance(x, dict):
        return "{" + ", ".join(f"{_show_nested(k)}: {_show_nested(v)}" for k, v in x.items()) + "}"
    return show(x)


def show_duration(seconds: float) -> str:
    """500ms, 2s, 1.5s, 5m, 1h 30m, 2d ..."""
    s = float(seconds)
    sign = "-" if s < 0 else ""
    s = abs(s)
    if s < 1:
        v = s * 1000
        return f"{sign}{v:g}ms"
    if s < 60:
        return f"{sign}{s:g}s"
    parts = []
    for unit, size in (("d", 86400), ("h", 3600), ("m", 60)):
        if s >= size:
            n = int(s // size)
            parts.append(f"{n}{unit}")
            s -= n * size
    if s:
        parts.append(f"{s:g}s")
    return sign + " ".join(parts)


def sleep(seconds: float) -> None:
    import time
    time.sleep(max(0.0, float(seconds)))


def fmt(x, spec: str) -> str:
    if spec == "":
        return show(x)
    if spec == "%":
        return f"{x * 100:g}%"
    return format(x, spec)


def fx_print(*values, sep: str = " ", end: str = "\n") -> None:
    sys.stdout.write(sep.join(show(v) for v in values) + end)
    sys.stdout.flush()      # long-running programs (servers) show their output straight away


def capitalize(s: str) -> str:
    return s[:1].upper() + s[1:]


def is_number(s: str) -> bool:
    try:
        float(s.replace("_", ""))
        return True
    except ValueError:  # the Python one
        return False


def to_int(s: str):
    try:
        return i64(int(s.strip().replace("_", "")))
    except Exception:  # noqa: BLE001
        return None


def to_float(s: str):
    try:
        return float(s.strip().replace("_", ""))
    except Exception:  # noqa: BLE001
        return None


_TRUE = {"true", "yes", "on", "1"}
_FALSE = {"false", "no", "off", "0"}


def to_bool(s: str):
    v = s.strip().lower()
    if v in _TRUE:
        return True
    if v in _FALSE:
        return False
    return None


def str_index(s: str, sub: str):
    i = s.find(sub)
    return None if i < 0 else i


# ---------------------------------------------------------------------------
# Collections (Syntax/collections.fx3)
# ---------------------------------------------------------------------------

def copy(x):
    """Value semantics: collections are copied on assignment; objects inside are shared."""
    if isinstance(x, list):
        return [copy(v) for v in x]
    if isinstance(x, dict):
        return {k: copy(v) for k, v in x.items()}
    if isinstance(x, set):
        return set(x)
    return x


def first(xs):
    return xs[0] if xs else None


def last(xs):
    return xs[-1] if xs else None


def pop(xs):
    return xs.pop() if xs else None


def pop_front(xs):
    return xs.pop(0) if xs else None


def get_or(xs, i, default):
    try:
        return xs[i]
    except (IndexError, KeyError):
        return default


def index_of(xs, value):
    for i, v in enumerate(xs):
        if v == value:
            return i
    return None


def remove_first(xs, value) -> None:
    for i, v in enumerate(xs):
        if v == value:
            del xs[i]
            return


def minimum(xs):
    return min(xs) if xs else None


def maximum(xs):
    return max(xs) if xs else None


def average(xs) -> float:
    if not xs:
        raise Panic("average of an empty collection")
    return sum(xs) / len(xs)


def neighbours(xs):
    """(index, value, previous, next) for every element."""
    n = len(xs)
    for i, v in enumerate(xs):
        yield i, v, (xs[i - 1] if i > 0 else None), (xs[i + 1] if i + 1 < n else None)


def get_index(xs, i):
    try:
        return xs[i]
    except IndexError:
        raise Panic(f"index {i} is out of range (size {len(xs)})") from None


def get_key(m, k):
    try:
        return m[k]
    except KeyError:
        raise Panic(f"key {_show_nested(k)} is not in the map") from None


def reduce(fn, xs, start=MISSING):
    if start is MISSING:
        if not xs:
            raise Panic("reduce of an empty collection with no start value")
        return functools.reduce(fn, xs)
    return functools.reduce(fn, xs, start)


def unwrap(x, message: str | None = None):
    if x is None:
        raise Panic(message or "unwrap() on none")
    return x


# ---------------------------------------------------------------------------
# result<T> and handling failures
# ---------------------------------------------------------------------------

class Result:
    __slots__ = ("value", "error")

    def __init__(self, value=None, error=None):
        self.value = value
        self.error = error

    def is_ok(self) -> bool:
        return self.error is None

    def is_error(self) -> bool:
        return self.error is not None

    def get_or(self, default):
        return self.value if self.error is None else default

    def unwrap(self, message: str | None = None):
        if self.error is not None:
            raise Panic(message or f"unwrap() on a failed result: {self.error}")
        return self.value

    def __repr__(self) -> str:
        return f"ok({show(self.value)})" if self.error is None else f"error({self.error})"


def capture(fn) -> Result:
    try:
        return Result(fn())
    except Error as e:
        return Result(None, e)


def try_or(fn, default_fn):
    """`mayFail() ?? default`"""
    try:
        return fn()
    except Error:
        return default_fn()


# ---------------------------------------------------------------------------
# Running a program
# ---------------------------------------------------------------------------

def expect_equal(actual, expected, label: str = "") -> None:
    if actual != expected:
        raise Panic(f"{label}expected {_show_nested(expected)}, got {_show_nested(actual)}")


def expect(cond: bool, label: str = "") -> None:
    if not cond:
        raise Panic(f"{label}expectation failed")


def _panic_message(exc: BaseException) -> str | None:
    if isinstance(exc, Panic):
        return str(exc)
    if isinstance(exc, IndexError):
        return "index out of range"
    if isinstance(exc, KeyError):
        return f"key {exc} is not in the map"
    if isinstance(exc, ZeroDivisionError):
        return "division by zero"
    if isinstance(exc, RecursionError):
        return "too much recursion"
    if isinstance(exc, Error):
        return f"unhandled failure: {exc}"
    return None


class program:
    """`with _rt.program():` around the top-level code: panics end the program with a clear message."""

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc, tb):
        if exc is None or isinstance(exc, SystemExit):
            return False
        msg = _panic_message(exc)
        if msg is None:
            return False
        sys.stdout.flush()
        sys.stderr.write(f"panic: {msg}\n")
        raise SystemExit(101)


def finish(main=None, tests=None, modules=None) -> None:
    """Runs @entry main, or the tests when started with --fx3-test (with those of the other project
    modules, named like `geo.shapes: area of a square`)."""
    if "--fx3-test" in sys.argv:
        everything = list(tests or [])
        for name in modules or []:
            import importlib
            mod = importlib.import_module(name)
            everything += [(f"{name}: {label}", fn) for label, fn in getattr(mod, "_FX3_TESTS", [])]
        run_tests(everything)
        return
    if main is not None:
        main()


def run_tests(tests) -> None:
    passed = failed = 0
    for name, fn in tests:
        try:
            fn()
            passed += 1
            sys.stdout.write(f"  ok    {name}\n")
        except BaseException as exc:  # noqa: BLE001
            failed += 1
            msg = _panic_message(exc) or f"{type(exc).__name__}: {exc}"
            sys.stdout.write(f"  FAIL  {name}: {msg}\n")
    sys.stdout.write(f"{passed} passed, {failed} failed\n")
    if failed:
        raise SystemExit(1)
